const { normalizeAgentTokenUsage } = require('../../../shared/agent_usage_math.mjs');
const { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage } = require('./agent_claude_events');
const { codexChangedPaths, codexTranscriptEvents } = require('./agent_codex_events');
const { JsonLineBuffer } = require('./agent_event_utils');

const MISSING_SESSION_CODES = new Set([
    'conversation_not_found',
    'invalid_session_id',
    'resume_session_not_found',
    'session_not_found',
    'thread_not_found',
]);

// Codex exec reports cached tokens as a subset of input_tokens; subtracting here makes inputTokens
// fresh-only, matching how claude reports them.
function codexUsage(event) {
    const usage = event.usage;
    if (event.type !== 'turn.completed' || !usage || typeof usage !== 'object' || Array.isArray(usage)) return null;
    const cachedInputTokens = usage.cached_input_tokens;

    return normalizeAgentTokenUsage({
        cachedInputTokens,
        inputTokens: (usage.input_tokens ?? 0) - (cachedInputTokens ?? 0),
        outputTokens: usage.output_tokens,
        reasoningTokens: usage.reasoning_output_tokens,
    });
}

function providerUsage(agent, event) {
    return agent === 'codex' ? codexUsage(event) : claudeUsage(event);
}

function providerChangedPaths(agent, event, rootPath) {
    if (agent !== 'codex') return claudeChangedPaths(event, rootPath);
    if (event.type !== 'item.completed') return [];

    return codexChangedPaths(event.item, rootPath);
}

function providerTranscriptEvents(agent, event) {
    if (agent !== 'codex') return claudeTranscriptEvents(event);
    if (event.type !== 'item.completed' || !event.item) return [];

    return codexTranscriptEvents(event.item);
}

function eventCodes(event) {
    return [event.code, event.error?.code, event.error?.type, event.result?.code, event.subtype]
        .filter((value) => typeof value === 'string')
        .map((value) => value.toLowerCase());
}

function codexAssistantText(event) {
    if (event.type !== 'item.completed' || event.item?.type !== 'agent_message') return '';

    return typeof event.item.text === 'string' ? event.item.text : '';
}

function nestedErrorMessage(value) {
    if (typeof value === 'string') {
        try {
            return nestedErrorMessage(JSON.parse(value));
        } catch {
            return value;
        }
    }
    if (!value || typeof value !== 'object' || Array.isArray(value)) return '';

    return nestedErrorMessage(value.message ?? value.error ?? value.result);
}

function providerErrorText(agent, event) {
    if (event.type === 'error') return nestedErrorMessage(event.message ?? event.error);
    if (agent === 'codex' && event.type === 'turn.failed') return nestedErrorMessage(event.error);
    if (agent === 'codex' && event.type === 'item.completed' && event.item?.type === 'error') {
        return nestedErrorMessage(event.item.message ?? event.item.error);
    }
    if (agent === 'claude' && event.type === 'result' && event.is_error === true) {
        return nestedErrorMessage(event.error ?? event.result ?? event.message);
    }

    return '';
}

function providerConversationId(agent, event) {
    if (agent === 'codex' && event.type === 'thread.started') return event.thread_id ?? event.thread?.thread_id ?? null;
    if (agent === 'claude' && typeof event.session_id === 'string') return event.session_id;

    return null;
}

function isTurnActivity(agent, event) {
    if (agent === 'codex') return event.type === 'turn.started' || event.type === 'item.started' || event.type === 'item.completed';
    if (agent === 'claude') return event.type === 'assistant' || event.type === 'user';

    return false;
}

function isMissingSession(agent, event, turnStarted) {
    if (turnStarted) return false;
    if (agent !== 'codex' && agent !== 'claude') return false;
    const isFailureEvent = event.type === 'error' || (agent === 'claude' && event.type === 'result' && event.is_error === true);

    return isFailureEvent && eventCodes(event).some((code) => MISSING_SESSION_CODES.has(code));
}

class AgentProviderProtocolParser {
    constructor(agent, onEvent, onMalformed, rootPath) {
        this.agent = agent;
        this.lines = new JsonLineBuffer(agent, (line) => this.parseLine(line));
        this.onEvent = onEvent;
        this.onMalformed = onMalformed;
        this.rootPath = rootPath;
        this.turnStarted = false;
    }

    push(chunk) {
        this.lines.push(chunk);
    }

    finish() {
        this.lines.finish();
    }

    parseLine(line) {
        let event;
        try {
            event = JSON.parse(line);
        } catch {
            this.onMalformed(line);
            return;
        }
        if (!event || typeof event !== 'object' || Array.isArray(event)) {
            this.onMalformed(line);
            return;
        }

        const missingSession = isMissingSession(this.agent, event, this.turnStarted);
        this.turnStarted = this.turnStarted || isTurnActivity(this.agent, event);
        const assistantText = this.agent === 'codex' ? codexAssistantText(event) : claudeAssistantText(event);
        this.onEvent({
            assistantText,
            changedPaths: providerChangedPaths(this.agent, event, this.rootPath),
            conversationId: providerConversationId(this.agent, event),
            errorText: providerErrorText(this.agent, event),
            missingSession,
            transcriptEvents: providerTranscriptEvents(this.agent, event),
            turnStarted: this.turnStarted,
            usage: providerUsage(this.agent, event),
        });
    }
}

function createAgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath) {
    if (agent !== 'codex' && agent !== 'claude') return null;

    return new AgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath);
}

module.exports = { createAgentProviderProtocolParser, isMissingSession };

const { normalizeAgentTokenUsage } = require('../../../shared/agent_usage_math.mjs');
const { claudeAssistantText, claudeChangedPaths, claudeTranscriptEvents, claudeUsage } = require('./agent_claude_events');
const { codexChangedPaths } = require('./agent_codex_events');
const { diagnosticActivity, normalizeCodexActivity, systemActivity } = require('./agent_codex_activity');
const { isMissingSession } = require('./agent_provider_protocol');

const CODEX_CLIENT_NAME = 'md2';
const CODEX_CLIENT_VERSION = '1';
const CODEX_MISSING_THREAD_ERROR_CODE = -32600;
const CLAUDE_QUESTION_TOOL = 'AskUserQuestion';
const CODEX_NON_ACTIVITY_ITEM_TYPES = new Set(['agentMessage', 'hookPrompt', 'userMessage']);

function requireMessage(content) {
    if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Streaming agent message is required');

    return content;
}

function claudeUserMessage(content) {
    return { message: { content, role: 'user' }, type: 'user' };
}

function claudeQuestionRequest(event) {
    if (event.type !== 'control_request' || event.request?.subtype !== 'can_use_tool') return null;
    if (event.request.tool_name !== CLAUDE_QUESTION_TOOL || !Array.isArray(event.request.input?.questions)) return null;

    const questions = event.request.input.questions.map((question, index) => ({
        ...question,
        id: question.id ?? `claude-question-${index}`,
    }));

    return {
        input: event.request.input,
        questions,
        requestId: event.request_id,
        toolUseId: event.request.tool_use_id,
    };
}

function claudeControlResponse(requestId, response) {
    return {
        response: { request_id: requestId, response, subtype: 'success' },
        type: 'control_response',
    };
}

function isClaudeMissingSessionResult(event, providerConversationId) {
    if (!providerConversationId || event.type !== 'result' || event.is_error !== true) return false;
    if (event.session_id !== providerConversationId || !Array.isArray(event.errors)) return false;

    return event.errors.includes(`No conversation found with session ID: ${providerConversationId}`);
}

class ClaudeStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.pendingQuestions = new Map();
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.turnStarted = false;
        /** Claude emits whole assistant messages, so the adapter adds the blank line between them. */
        this.turnHasAssistantText = false;
    }

    async start(prompt) {
        await this.sendMessage(prompt);
    }

    async sendMessage(content) {
        await this.writeLine(claudeUserMessage(requireMessage(content)));
    }

    async answerQuestion(requestId, answers) {
        const pendingQuestion = this.pendingQuestions.get(requestId);
        if (!pendingQuestion) throw new Error(`Unknown Claude question request id: ${requestId}`);
        const mappedAnswers = Object.fromEntries(pendingQuestion.questions.map(({ id, question }) => {
            if (!Object.hasOwn(answers, id)) throw new Error(`Missing answer for Claude question: ${id}`);

            return [question, answers[id]];
        }));
        const updatedInput = { ...pendingQuestion.input, answers: mappedAnswers };
        const response = { behavior: 'allow', toolUseID: pendingQuestion.toolUseId, updatedInput };
        await this.writeLine(claudeControlResponse(requestId, response));
        this.pendingQuestions.delete(requestId);
    }

    async handleMessage(event) {
        const questionRequest = claudeQuestionRequest(event);
        if (questionRequest) {
            this.pendingQuestions.set(questionRequest.requestId, questionRequest);
            await this.onEvent({
                questions: questionRequest.questions,
                requestId: questionRequest.requestId,
                type: 'question',
            });
            return;
        }
        if (event.type === 'control_request' && event.request?.subtype === 'can_use_tool') {
            const response = {
                behavior: 'deny',
                message: 'Interactive tool approval is not supported',
                toolUseID: event.request.tool_use_id,
            };
            await this.writeLine(claudeControlResponse(event.request_id, response));
            return;
        }
        if (event.type === 'system' && typeof event.session_id === 'string') {
            await this.onEvent({ conversationId: event.session_id, type: 'sessionStarted' });
        }
        const startsTurn = event.type === 'assistant' || event.type === 'user';
        if (!this.turnStarted && startsTurn) await this.onEvent({ type: 'turnStarted' });
        this.turnStarted = this.turnStarted || startsTurn;
        const assistantText = claudeAssistantText(event);
        if (assistantText.length > 0) {
            const separator = this.turnHasAssistantText ? '\n\n' : '';
            this.turnHasAssistantText = true;
            await this.onEvent({ content: `${separator}${assistantText}`, type: 'assistant' });
        }
        const changedPaths = claudeChangedPaths(event, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        for (const transcriptEvent of claudeTranscriptEvents(event)) {
            await this.onEvent({ ...transcriptEvent, type: 'transcript' });
        }
        if (event.type === 'result') {
            const error = event.is_error === true
                ? String(event.error ?? event.result ?? event.message ?? event.errors?.join('\n') ?? 'Claude turn failed')
                : null;
            const missingSession = !this.turnStarted && (
                isClaudeMissingSessionResult(event, this.providerConversationId)
                || isMissingSession('claude', event, this.turnStarted)
            );
            this.turnHasAssistantText = false;
            await this.onEvent({ error, missingSession, type: 'turnCompleted', usage: claudeUsage(event) });
        }
    }
}

function codexInput(content) {
    return [{ text: requireMessage(content), type: 'text' }];
}

// The app-server already reports cache-free input tokens, unlike `codex exec`, so no subtraction here.
function codexUsage(params) {
    const usage = params.tokenUsage?.last;
    if (!usage) return null;

    return normalizeAgentTokenUsage({
        cachedInputTokens: usage.cachedInputTokens,
        inputTokens: usage.inputTokens,
        outputTokens: usage.outputTokens,
        reasoningTokens: usage.reasoningOutputTokens,
    });
}

function ensureActivityTextPart(activity, field, index) {
    if (!Number.isSafeInteger(index) || index < 0) return;
    while (activity[field].length <= index) activity[field].push('');
}

function isCodexMissingThreadError(error, providerConversationId) {
    if (!providerConversationId || error?.code !== CODEX_MISSING_THREAD_ERROR_CODE) return false;

    return error.message === `no rollout found for thread id ${providerConversationId}`;
}

class CodexStreamingAdapter {
    constructor(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent) {
        this.writeLine = writeLine;
        this.onEvent = onEvent;
        this.onRuntimeEvent = onRuntimeEvent;
        this.providerConversationId = providerConversationId;
        this.rootPath = rootPath;
        this.activeTurnId = null;
        this.activeItems = new Map();
        this.assistantItemOrder = [];
        this.assistantStreams = new Map();
        this.completedItemIds = new Set();
        this.diagnosticSequence = 1;
        this.initialPrompt = null;
        this.nextRequestId = 1;
        this.pendingRequests = new Map();
        this.threadId = null;
        this.turnUsage = null;
    }

    async start(prompt) {
        this.initialPrompt = requireMessage(prompt);
        await this.sendRequest('initialize', {
            capabilities: { experimentalApi: true },
            clientInfo: { name: CODEX_CLIENT_NAME, version: CODEX_CLIENT_VERSION },
        }, 'initialize');
    }

    async sendMessage(content) {
        const input = codexInput(content);
        if (!this.threadId) throw new Error('Codex streaming thread is not ready');
        if (this.activeTurnId) {
            await this.sendRequest('turn/steer', {
                expectedTurnId: this.activeTurnId,
                input,
                threadId: this.threadId,
            });
            return;
        }
        await this.sendRequest('turn/start', { input, threadId: this.threadId });
    }

    async answerQuestion(requestId, answers) {
        if (requestId === null || requestId === undefined) throw new Error('Missing Codex question request id');
        const normalizedAnswers = Object.fromEntries(Object.entries(answers).map(([questionId, answer]) => [
            questionId,
            { answers: Array.isArray(answer) ? answer : [answer] },
        ]));
        await this.writeLine({ id: requestId, result: { answers: normalizedAnswers } });
    }

    async sendRequest(method, params, purpose = null) {
        const id = this.nextRequestId;
        this.nextRequestId += 1;
        if (purpose) this.pendingRequests.set(id, purpose);
        try {
            await this.writeLine({ id, method, params });
        } catch (error) {
            this.pendingRequests.delete(id);
            throw error;
        }
    }

    async handleMessage(message) {
        if (Object.hasOwn(message, 'id') && !message.method) {
            await this.handleResponse(message);
            return;
        }
        if (message.method === 'item/tool/requestUserInput') {
            await this.onEvent({ questions: message.params.questions, requestId: message.id, type: 'question' });
            return;
        }
        await this.handleNotification(message.method, message.params ?? {});
    }

    async handleResponse(message) {
        const purpose = this.pendingRequests.get(message.id);
        if (!purpose) {
            if (message.error) await this.onEvent({ content: message.error.message ?? 'Codex request failed', type: 'fatal' });
            return;
        }
        this.pendingRequests.delete(message.id);
        if (message.error) {
            const content = message.error.message ?? `Codex ${purpose} failed`;
            if (purpose === 'rateLimitsRead') {
                await this.onRuntimeEvent({ kind: 'unavailable', observedAt: Date.now() });
                return;
            }
            if (purpose === 'threadResume') {
                const missingSession = isCodexMissingThreadError(message.error, this.providerConversationId)
                    || isMissingSession('codex', { error: message.error, type: 'error' }, false);
                await this.onEvent({ content, missingSession, type: 'sessionFailed' });
                return;
            }
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (purpose === 'initialize') {
            await this.writeLine({ method: 'initialized', params: {} });
            await this.sendRequest('account/rateLimits/read', undefined, 'rateLimitsRead');
            if (this.providerConversationId) {
                await this.sendRequest('thread/resume', {
                    cwd: this.rootPath,
                    threadId: this.providerConversationId,
                }, 'threadResume');
                return;
            }
            await this.sendRequest('thread/start', { cwd: this.rootPath }, 'threadStart');
            return;
        }
        if (purpose === 'threadStart' || purpose === 'threadResume') {
            this.threadId = message.result?.thread?.id ?? message.result?.threadId ?? this.providerConversationId;
            if (!this.threadId) throw new Error('Codex app-server did not return a thread id');
            await this.onEvent({ conversationId: this.threadId, type: 'sessionStarted' });
            await this.sendMessage(this.initialPrompt);
            return;
        }
        if (purpose === 'rateLimitsRead') {
            const hasSingleBucket = !!message.result?.rateLimits && typeof message.result.rateLimits === 'object';
            const hasBuckets = !!message.result?.rateLimitsByLimitId
                && typeof message.result.rateLimitsByLimitId === 'object'
                && Object.keys(message.result.rateLimitsByLimitId).length > 0;
            await this.onRuntimeEvent(hasSingleBucket || hasBuckets
                ? { kind: 'snapshot', observedAt: Date.now(), payload: message.result }
                : { kind: 'unavailable', observedAt: Date.now() });
        }
    }

    async handleNotification(method, params) {
        if (method === 'turn/started') {
            this.activeItems.clear();
            this.assistantItemOrder = [];
            this.assistantStreams.clear();
            this.completedItemIds.clear();
            this.activeTurnId = params.turn?.id ?? params.turnId;
            await this.onEvent({ turnId: this.activeTurnId, type: 'turnStarted' });
            return;
        }
        if (method === 'item/started') {
            await this.handleItemStarted(method, params.item);
            return;
        }
        if (method === 'item/agentMessage/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'agentMessage');
            if (!trackedItem) return;
            trackedItem.assistantText = trackedItem.assistantText || params.delta.length > 0;
            trackedItem.bufferedAssistantText += params.delta;
            await this.flushAssistantStreams();
            return;
        }
        if (method === 'item/reasoning/summaryTextDelta') {
            await this.handleReasoningDelta(method, params, 'summary', params.summaryIndex);
            return;
        }
        if (method === 'item/reasoning/summaryPartAdded') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
            if (!trackedItem) return;
            ensureActivityTextPart(trackedItem.activity, 'summary', params.summaryIndex);
            await this.emitActivity(trackedItem.activity);
            return;
        }
        if (method === 'item/reasoning/textDelta') {
            await this.handleReasoningDelta(method, params, 'details', params.contentIndex);
            return;
        }
        if (method === 'item/commandExecution/outputDelta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'commandExecution');
            if (!trackedItem) return;
            trackedItem.activity.output += params.delta;
            trackedItem.activity.content = trackedItem.activity.output;
            await this.emitActivity(trackedItem.activity);
            return;
        }
        if (method === 'item/plan/delta') {
            const trackedItem = await this.requireActiveItem(method, params.itemId, 'plan');
            if (!trackedItem) return;
            trackedItem.activity.content += params.delta;
            await this.emitActivity(trackedItem.activity);
            return;
        }
        if (method === 'thread/tokenUsage/updated') {
            this.turnUsage = codexUsage(params);
            return;
        }
        if (method === 'account/rateLimits/updated') {
            await this.onRuntimeEvent({ kind: 'update', observedAt: Date.now(), payload: params });
            return;
        }
        if (method === 'item/completed') {
            await this.handleItemCompleted(method, params.item);
            return;
        }
        const normalizedSystemActivity = systemActivity(method, params);
        if (normalizedSystemActivity) {
            await this.emitActivity(normalizedSystemActivity);
            return;
        }
        if (method === 'error') {
            const content = params.error?.message ?? 'Codex turn failed';
            await this.emitActivity({
                content,
                label: 'Turn failure',
                providerItemId: `system:${this.activeTurnId ?? 'unknown-turn'}:error`,
                status: 'failed',
                type: 'system',
            });
            await this.onEvent({ content, type: 'fatal' });
            return;
        }
        if (method === 'turn/completed') {
            const error = params.turn?.status === 'failed'
                ? params.turn.error?.message ?? 'Codex turn failed'
                : null;
            if (error) {
                await this.emitActivity({
                    content: error,
                    label: 'Turn failure',
                    providerItemId: `system:${params.turn?.id ?? this.activeTurnId ?? 'unknown-turn'}:turn/completed`,
                    status: 'failed',
                    type: 'system',
                });
            }
            this.activeTurnId = null;
            await this.onEvent({ error, type: 'turnCompleted', usage: this.turnUsage });
            this.turnUsage = null;
            return;
        }
        if (method?.startsWith('item/') && typeof params.itemId === 'string') {
            await this.emitDiagnostic(method, null, params.itemId);
        }
    }

    async handleItemStarted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.activeItems.has(item.id) || this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const activity = normalizeCodexActivity(item, 'inProgress');
        const knownNonActivity = CODEX_NON_ACTIVITY_ITEM_TYPES.has(item.type);
        const trackedItem = {
            activity,
            assistantCompleted: false,
            assistantText: false,
            bufferedAssistantText: '',
            itemType: item.type,
        };
        this.activeItems.set(item.id, trackedItem);
        if (item.type === 'agentMessage') {
            this.assistantItemOrder.push(item.id);
            this.assistantStreams.set(item.id, trackedItem);
            await this.onEvent({ itemId: item.id, type: 'assistantStarted' });
        }
        if (activity) {
            await this.emitActivity(activity);
            return;
        }
        if (!knownNonActivity) await this.emitDiagnostic(method, item.type, item.id);
    }

    async handleItemCompleted(method, item) {
        if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') {
            await this.emitDiagnostic(method, item?.type, item?.id);
            return;
        }
        if (this.completedItemIds.has(item.id)) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        const trackedItem = this.activeItems.get(item.id);
        if (!trackedItem) await this.emitDiagnostic(method, item.type, item.id);
        if (trackedItem && trackedItem.itemType !== item.type) {
            await this.emitDiagnostic(method, item.type, item.id);
            return;
        }
        if (item.type === 'agentMessage' && trackedItem) {
            trackedItem.assistantCompleted = true;
            await this.flushAssistantStreams();
        }
        const changedPaths = codexChangedPaths(item, this.rootPath);
        if (changedPaths.length > 0) await this.onEvent({ paths: changedPaths, type: 'changedPaths' });
        const activity = normalizeCodexActivity(item, 'completed');
        if (activity) await this.emitActivity(activity);
        if (!activity && !CODEX_NON_ACTIVITY_ITEM_TYPES.has(item.type) && trackedItem) {
            await this.emitDiagnostic(method, item.type, item.id);
        }
        this.activeItems.delete(item.id);
        this.completedItemIds.add(item.id);
    }

    async requireActiveItem(method, itemId, expectedType) {
        const trackedItem = this.activeItems.get(itemId);
        if (!trackedItem || trackedItem.itemType !== expectedType || this.completedItemIds.has(itemId)) {
            await this.emitDiagnostic(method, expectedType, itemId);

            return null;
        }

        return trackedItem;
    }

    async handleReasoningDelta(method, params, field, index) {
        const trackedItem = await this.requireActiveItem(method, params.itemId, 'reasoning');
        if (!trackedItem || !Number.isSafeInteger(index) || index < 0) {
            if (trackedItem) await this.emitDiagnostic(method, 'reasoning', params.itemId);
            return;
        }
        ensureActivityTextPart(trackedItem.activity, field, index);
        trackedItem.activity[field][index] += params.delta;
        trackedItem.activity.content = trackedItem.activity.summary.length > 0
            ? trackedItem.activity.summary.join('\n\n')
            : trackedItem.activity.details.join('\n\n');
        await this.emitActivity(trackedItem.activity);
    }

    async flushAssistantStreams() {
        while (this.assistantItemOrder.length > 0) {
            const itemId = this.assistantItemOrder[0];
            const stream = this.assistantStreams.get(itemId);
            if (!stream) {
                this.assistantItemOrder.shift();
                continue;
            }
            if (stream.bufferedAssistantText.length > 0) {
                const content = stream.bufferedAssistantText;
                stream.bufferedAssistantText = '';
                await this.onEvent({ content, itemId, type: 'assistant' });
            }
            if (!stream.assistantCompleted) return;
            if (stream.assistantText) await this.onEvent({ content: '\n\n', itemId, type: 'assistant' });
            this.assistantStreams.delete(itemId);
            this.assistantItemOrder.shift();
        }
    }

    async emitActivity(activity) {
        await this.onEvent({ activity: structuredClone(activity), type: 'activity' });
    }

    async emitDiagnostic(method, itemType, itemId) {
        const activity = diagnosticActivity(method, itemType, itemId, this.diagnosticSequence);
        this.diagnosticSequence += 1;
        await this.emitActivity(activity);
    }
}

function createAgentStreamingAdapter(
    agent,
    writeLine,
    onEvent,
    rootPath,
    providerConversationId = null,
    onRuntimeEvent = async () => undefined,
) {
    if (agent === 'claude') return new ClaudeStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId);
    if (agent === 'codex') {
        return new CodexStreamingAdapter(writeLine, onEvent, rootPath, providerConversationId, onRuntimeEvent);
    }

    throw new Error(`Agent profile does not support streaming: ${agent}`);
}

module.exports = { createAgentStreamingAdapter };

const { normalizeChangedPaths, normalizedContent } = require('./agent_event_utils');

const CODEX_FILE_ITEM_KEYS = new Set(['file', 'filechange', 'patch']);
const CODEX_SILENT_ITEM_KEYS = new Set(['agentmessage', 'usermessage', 'reasoning', 'error']);

/**
 * `codex exec` and the codex app-server are different wire protocols and keep separate handlers,
 * but they describe the same item vocabulary in different casings (`file_change` / `fileChange`).
 * Only that shared vocabulary lives here; parsing stays with each protocol.
 */
function codexItemKey(item) {
    return typeof item?.type === 'string' ? item.type.replace(/[^a-z]/giu, '').toLowerCase() : '';
}

function isCodexFileItem(item) {
    return CODEX_FILE_ITEM_KEYS.has(codexItemKey(item));
}

function codexChangedPaths(item, rootPath) {
    if (!isCodexFileItem(item)) return [];
    const filePaths = typeof item.path === 'string' ? [item.path] : [];
    if (Array.isArray(item.changes)) filePaths.push(...item.changes.map((change) => change?.path));

    return normalizeChangedPaths(rootPath, filePaths);
}

/** Assistant messages, user echoes and reasoning reach the conversation elsewhere; skip them here. */
function codexTranscriptContent(item) {
    if (!item || CODEX_SILENT_ITEM_KEYS.has(codexItemKey(item))) return null;

    return normalizedContent(
        item.aggregated_output
        ?? item.aggregatedOutput
        ?? item.output
        ?? item.result
        ?? item.changes
        ?? item.command
        ?? item.path
        ?? item.name,
    );
}

function codexTranscriptEvents(item) {
    const content = codexTranscriptContent(item);

    return content ? [{ content, toolType: `tool.${item.type}` }] : [];
}

module.exports = { codexChangedPaths, codexTranscriptEvents };

const crypto = require('node:crypto');
const path = require('node:path');
const crossSpawn = require('cross-spawn');

const {
    accumulateUsage,
    createActivityEvent,
    createConversation,
    createEvent,
    createMessage,
    updateProviderSession,
} = require('./agent_conversation');
const {
    conversationReference,
    persistConversation,
    persistConversationCheckpoint,
} = require('./agent_conversation_persistence');
const { JsonLineBuffer } = require('./agent_event_utils');
const { createAgentProviderProtocolParser } = require('./agent_provider_protocol');
const { createAgentStreamingAdapter } = require('./agent_streaming_adapter');
const { AgentExecutableResolver } = require('./agent_executable_availability');
const { createAgentEnvironment } = require('./agent_environment');
const { diagnoseCodexCacheError, isCodexCacheError } = require('./agent_codex_cache_diagnostic');
const { terminateDescendantProcesses, terminateProcessTree } = require('./process_tree');
const { assertGitRoot, ensureInsideRoot, requireRootPath } = require('../git/git_commands');

const HIDDEN_STDERR_LINES = [
    /^completed$/i,
    /^Debugger listening on ws:\/\//,
    /^For help, see: https:\/\/nodejs\.org\/en\/docs\/inspector\/?$/,
    /^Debugger attached\.$/,
    /^Reading additional input from stdin\.\.\.$/,
    /^Waiting for the debugger to disconnect\.\.\.$/,
];

function isHiddenStderrLine(line) {
    return HIDDEN_STDERR_LINES.some((pattern) => pattern.test(line.trim()));
}

function filterCompleteStderrLines(content) {
    const parts = content.split(/(\r\n|\r|\n)/);
    const remainder = parts.pop();
    const visibleParts = [];
    for (let index = 0; index < parts.length; index += 2) {
        const line = parts[index];
        const delimiter = parts[index + 1];
        if (!isHiddenStderrLine(line)) visibleParts.push(`${line}${delimiter}`);
    }

    return { content: visibleParts.join(''), remainder };
}

function requireString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing agent ${fieldName}`);

    return value;
}

function requireProjectFolder(value) {
    if (typeof value !== 'string') throw new Error('Missing agent projectFolder');

    return value;
}

function requireCommand(value) {
    if (!Array.isArray(value) || value.length === 0) throw new Error('Missing agent command');
    value.forEach((argument, index) => requireString(argument, `command[${index}]`));

    return value;
}

function readOptionalString(value, fieldName) {
    if (value === undefined || value === null) return null;
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Missing agent ${fieldName}`);

    return value;
}

function emitRunEvent(run, event) {
    if (!run.onEvent) return;

    run.onEvent({ ...event, runId: run.id });
}

function writeJsonLine(stream, message) {
    return new Promise((resolve, reject) => {
        stream.write(`${JSON.stringify(message)}\n`, (error) => {
            if (error) {
                reject(error);
                return;
            }

            resolve();
        });
    });
}

function queueInteractionWrite(run, operation) {
    run.interactionWrites ??= Promise.resolve();
    const write = run.interactionWrites.then(operation);
    run.interactionWrites = write.catch(() => undefined);

    return write;
}

function secretAnswerValues(questions, answers) {
    const secretQuestionIds = new Set(questions.filter(({ isSecret }) => isSecret).map(({ id }) => id));

    return Object.entries(answers)
        .filter(([questionId]) => secretQuestionIds.has(questionId))
        .flatMap(([, answer]) => Array.isArray(answer) ? answer : [answer])
        .filter((answer) => typeof answer === 'string' && answer.length > 0);
}

function redactSecrets(content, secretValues) {
    if (typeof content !== 'string' || !secretValues || secretValues.size === 0) return content;

    return [...secretValues]
        .sort((first, second) => second.length - first.length)
        .reduce((redacted, secret) => redacted.split(secret).join('[secret]'), content);
}

function redactTextArray(values, secretValues) {
    return values.map((value) => redactSecrets(value, secretValues));
}

function redactActivity(activity, secretValues) {
    return {
        ...activity,
        command: redactSecrets(activity.command, secretValues),
        content: redactSecrets(activity.content, secretValues),
        details: Array.isArray(activity.details) ? redactTextArray(activity.details, secretValues) : activity.details,
        label: redactSecrets(activity.label, secretValues),
        output: redactSecrets(activity.output, secretValues),
        summary: Array.isArray(activity.summary) ? redactTextArray(activity.summary, secretValues) : activity.summary,
        workingDirectory: redactSecrets(activity.workingDirectory, secretValues),
    };
}

function requireQueuedMessageSession(run, sessionId) {
    if (!Number.isSafeInteger(sessionId) || sessionId <= 0) throw new Error('Invalid queued agent message session');
    if (sessionId !== run.queuedMessageSessionId) throw new Error('Queued agent message session expired');
}

function nextConversationSequence(conversation) {
    const entries = [...conversation.messages, ...conversation.events];
    const highestSequence = entries.reduce((highest, entry) => (
        Number.isSafeInteger(entry.sequence) ? Math.max(highest, entry.sequence) : highest
    ), 0);

    return Math.max(highestSequence, entries.length) + 1;
}

function nextRunSequence(run) {
    const sequence = run.nextSequence;
    run.nextSequence += 1;

    return sequence;
}

function createActivityEventIndexes(events) {
    const activityEventIndexes = new Map();
    for (const [index, { providerItemId }] of events.entries()) {
        if (typeof providerItemId === 'string' && !activityEventIndexes.has(providerItemId)) {
            activityEventIndexes.set(providerItemId, index);
        }
    }

    return activityEventIndexes;
}

function assistantMessageId(run) {
    return run.streaming ? `${run.id}-turn-${run.turnIndex}-assistant` : `${run.id}-assistant`;
}

function startAssistantItem(run, itemId) {
    if (run.assistantItems.has(itemId)) throw new Error(`Duplicate assistant item ${itemId}`);
    run.assistantItemIndex += 1;
    const item = {
        messageId: `${run.id}-turn-${run.turnIndex}-assistant-${run.assistantItemIndex}`,
        sequence: nextRunSequence(run),
    };
    run.assistantItems.set(itemId, item);
    run.currentAssistantMessageId = item.messageId;

    return item;
}

function assistantItem(run, itemId) {
    if (!itemId) return null;
    const item = run.assistantItems.get(itemId);
    if (!item) throw new Error(`Missing assistant item ${itemId}`);

    return item;
}

/**
 * Exact text appended to `existing` for `chunk`, including the paragraph separator.
 * Streaming chunks are provider deltas that must concatenate verbatim; the adapter owns their separators.
 */
function chunkSegment(existing, chunk, streaming) {
    if (streaming) return chunk;

    const trimmed = chunk.replace(/^\n+|\n+$/g, '');
    if (trimmed.length === 0) return '';
    if (existing.length === 0) return trimmed;

    return `\n\n${trimmed}`;
}

function joinChunk(existing, chunk, streaming) {
    return `${existing}${chunkSegment(existing, chunk, streaming)}`;
}

/** Appends a chunk and returns the appended segment, so streamed events carry the same separators. */
function appendAssistantOutput(run, content, timestamp, itemId = null) {
    const segment = chunkSegment(run.stdout, content, run.streaming);
    run.stdout += segment;
    const item = assistantItem(run, itemId);
    const messageId = item?.messageId ?? assistantMessageId(run);
    const currentIndex = run.conversation.messages.findIndex(({ id }) => id === messageId);
    if (currentIndex < 0) {
        const initialContent = run.streaming ? content : content.replace(/^\n+|\n+$/g, '');
        const message = createMessage(
            messageId,
            'assistant',
            initialContent,
            timestamp,
            run.agent,
            item?.sequence ?? nextRunSequence(run),
        );
        run.conversation.messages.push(message);

        return { message, segment };
    }

    const current = run.conversation.messages[currentIndex];
    const message = { ...current, content: joinChunk(current.content, content, run.streaming), timestamp };
    run.conversation.messages[currentIndex] = message;

    return { message, segment };
}

function completeAssistantOutput(run, completedAt) {
    const messageId = run.currentAssistantMessageId ?? assistantMessageId(run);
    const currentIndex = run.conversation.messages.findIndex(({ id }) => id === messageId);
    if (currentIndex < 0) return;

    run.conversation.messages[currentIndex] = { ...run.conversation.messages[currentIndex], timestamp: completedAt };
}

function createRunResult(request, exitCode, run) {
    return {
        command: request.command,
        conversation: { ...run.conversation, path: run.reference },
        exitCode,
        missingSession: run.missingSession,
        prompt: request.prompt,
        reference: run.reference,
        runId: run.id,
        stderr: run.stderr,
        stdout: run.stdout,
        changedPaths: [...run.changedPaths],
        turnStarted: run.turnStarted,
    };
}

class AgentRunnerService {
    constructor(dependencies = {}) {
        this.codexRuntimeService = dependencies.codexRuntimeService ?? null;
        this.persistConversation = dependencies.persistConversation
            ?? dependencies.persistTerminalConversation
            ?? persistConversation;
        this.persistConversationCheckpoint = dependencies.persistConversationCheckpoint
            ?? persistConversationCheckpoint;
        this.executableResolver = dependencies.executableResolver ?? new AgentExecutableResolver();
        this.diagnoseCodexCacheError = dependencies.diagnoseCodexCacheError ?? diagnoseCodexCacheError;
        this.terminateDescendantProcesses = dependencies.terminateDescendantProcesses ?? terminateDescendantProcesses;
        this.terminateProcessTree = dependencies.terminateProcessTree ?? terminateProcessTree;
        this.processes = new Map();
        this.runningConversationIds = new Set();
    }

    async run(project, request, onEvent) {
        let resolveCompletion;
        let rejectCompletion;
        const completion = new Promise((resolve, reject) => {
            resolveCompletion = resolve;
            rejectCompletion = reject;
        });
        const onComplete = (exitCode, run) => resolveCompletion(createRunResult(request, exitCode, run));
        const onCompletionError = (error) => rejectCompletion(error);

        await this.start(project, request, onEvent, onComplete, onCompletionError);

        return completion;
    }

    async start(project, requestValue, onEvent, onComplete, onCompletionError) {
        const request = {
            activityOrigin: { kind: 'project' },
            activityProject: project,
            ...requestValue,
        };
        const rootPath = requireRootPath(project);
        await assertGitRoot(rootPath);
        const command = requireCommand(request?.command);
        readOptionalString(request?.actionId, 'actionId');
        const cardPath = readOptionalString(request?.cardPath, 'cardPath');
        const prompt = requireString(request?.prompt, 'prompt');
        const agent = requireString(request?.agent ?? 'generic', 'agent');
        const streaming = request.streaming === true;
        requireProjectFolder(request?.projectFolder);
        if (cardPath) ensureInsideRoot(rootPath, path.join(rootPath, cardPath));

        const id = `agent-turn-${crypto.randomUUID()}`;
        const startedAt = new Date().toISOString();
        const conversation = createConversation(request, `agent-${crypto.randomUUID()}`, startedAt);
        let nextSequence = nextConversationSequence(conversation);
        if (this.runningConversationIds.has(conversation.id)) throw new Error(`Agent conversation already has a running turn: ${conversation.id}`);
        const reference = request.reference ?? conversationReference(request, conversation.id);
        const lastMessage = conversation.messages.at(-1);
        if (request.reuseLastUserMessage) {
            if (lastMessage?.role !== 'user' || lastMessage.content !== prompt) throw new Error('Missing failed-turn user message for agent retry');
        } else {
            conversation.messages.push(createMessage(`${id}-user`, 'user', prompt, startedAt, undefined, nextSequence));
            nextSequence += 1;
        }
        conversation.events.push(createEvent(`${id}-started`, 'started', command.join(' '), startedAt, nextSequence));
        nextSequence += 1;
        const [configuredExecutable, ...configuredArguments] = command;
        const environment = createAgentEnvironment(process.env);
        const resolvedExecutable = await this.executableResolver.find(configuredExecutable, { cwd: rootPath, env: environment });
        const executable = resolvedExecutable ?? configuredExecutable;
        const argumentsList = streaming ? configuredArguments : [...configuredArguments, prompt];
        const child = crossSpawn(executable, argumentsList, {
            cwd: rootPath,
            env: environment,
            stdio: ['pipe', 'pipe', 'pipe'],
            // windowsHide: true,
        });
        console.log('[agent:start]', {
            arguments: configuredArguments,
            cwd: rootPath,
            executionId: request.executionId ?? null,
            executable,
            pid: child.pid,
            runId: id,
            startedAt,
        });
        const { promise: closed, resolve: resolveClosed } = Promise.withResolvers();
        const run = {
            activityEventIndexes: createActivityEventIndexes(conversation.events),
            agent,
            assistantItemIndex: 0,
            assistantItems: new Map(),
            cancelled: false,
            child,
            changedPaths: new Set(),
            closed,
            conversation,
            codexCacheErrorReported: false,
            currentAssistantMessageId: null,
            environment,
            executable,
            id,
            missingSession: false,
            nextSequence,
            onComplete,
            onCompletionError,
            onEvent,
            interactionWrites: Promise.resolve(),
            pendingQuestions: [],
            persistence: Promise.resolve(),
            providerConversationId: null,
            protocolLines: null,
            protocolHandling: Promise.resolve(),
            reference,
            reportedProviderErrors: new Set(),
            resolveClosed,
            queuedMessage: null,
            queuedMessageRevision: -1,
            sentQueuedMessageRevision: -1,
            queuedMessageSessionId: 0,
            secretValues: new Set(),
            request,
            stderr: '',
            stderrBuffer: '',
            stderrHandling: Promise.resolve(),
            finishing: false,
            stdout: '',
            startedAt,
            streaming,
            streamingFailure: null,
            turnStarted: false,
            turnIndex: 1,
            turnActive: streaming,
            termination: null,
            suspended: false,
            turnUsage: null,
            waitingForQuestion: false,
        };
        const writeLine = (message) => writeJsonLine(child.stdin, message);
        run.streamingAdapter = streaming
            ? createAgentStreamingAdapter(
                agent,
                writeLine,
                (event) => this.handleStreamingEvent(id, event),
                rootPath,
                request.providerConversationId,
                (event) => this.handleCodexRuntimeEvent(event),
            )
            : null;
        run.protocolLines = streaming ? new JsonLineBuffer(id, (line) => this.handleStreamingLine(id, line)) : null;
        run.parser = streaming
            ? null
            : createAgentProviderProtocolParser(
                agent,
                (event) => this.handleProviderEvent(id, event),
                (line) => this.handleMalformedOutput(id, line),
                rootPath,
            );
        this.processes.set(id, run);
        this.runningConversationIds.add(conversation.id);

        child.stdout.on('data', (chunk) => this.handleOutput(id, 'stdout', chunk));
        child.stderr.on('data', (chunk) => this.handleOutput(id, 'stderr', chunk));
        child.on('error', (error) => this.handleError(id, error));
        child.stdin.on('error', (error) => this.handleError(id, error));
        child.on('close', (exitCode) => {
            void this.handleClose(id, exitCode ?? 1).finally(run.resolveClosed);
        });
        if (streaming) {
            const initialPrompt = typeof request.contextInput === 'string' && request.contextInput.length > 0
                ? `${request.contextInput}\n\n[User]\n\n${prompt}`
                : prompt;
            try {
                await run.streamingAdapter.start(initialPrompt);
            } catch (error) {
                this.failStreamingRun(run, error);
            }
        } else {
            if (typeof request.contextInput === 'string' && request.contextInput.length > 0) child.stdin.write(request.contextInput);
            child.stdin.end();
        }
        const userMessage = conversation.messages.at(-1);
        if (!userMessage || userMessage.role !== 'user') throw new Error('Missing current agent user message');
        emitRunEvent(run, {
            continued: !!request.conversation,
            conversationId: conversation.id,
            reference,
            startedAt,
            title: conversation.title,
            type: 'started',
            userMessage,
        });

        return { conversation: { ...conversation, path: reference }, reference, runId: id };
    }

    stop(runId) {
        const run = this.requireRun(runId);
        run.cancelled = true;
        run.queuedMessage = null;

        return this.ensureTermination(run);
    }

    suspend(runId) {
        const run = this.requireRun(runId);
        run.suspended = true;
        run.queuedMessage = null;

        return this.ensureTermination(run);
    }

    beginQueuedMessageDraft(runId) {
        const run = this.requireRun(runId);
        run.queuedMessageSessionId += 1;
        run.queuedMessage = null;
        run.queuedMessageRevision = -1;
        run.sentQueuedMessageRevision = -1;

        return run.queuedMessageSessionId;
    }

    sendMessage(runId, content) {
        const run = this.requireStreamingRun(runId);
        if (typeof content !== 'string' || content.trim().length === 0) throw new Error('Agent message is required');

        return queueInteractionWrite(run, async () => {
            await this.sendStreamingMessage(run, content);
            run.queuedMessage = null;
        });
    }

    sendQueuedMessage(runId, sessionId, revision) {
        const run = this.requireRun(runId);
        requireQueuedMessageSession(run, sessionId);
        if (!Number.isSafeInteger(revision) || revision < 0) throw new Error('Invalid queued agent message revision');

        return queueInteractionWrite(run, async () => {
            requireQueuedMessageSession(run, sessionId);
            if (revision <= run.sentQueuedMessageRevision) throw new Error('Queued agent message was already sent');
            if (!run.queuedMessage) throw new Error('Queued agent message is empty');
            if (run.queuedMessage.revision !== revision) throw new Error('Queued agent message changed before it was sent');
            if (!run.streaming) throw new Error('Queued agent messaging requires a streaming agent');

            const { content, revision: queuedRevision } = run.queuedMessage;
            await this.sendStreamingMessage(run, content);
            run.queuedMessage = null;
            run.sentQueuedMessageRevision = queuedRevision;

            return { sent: true };
        });
    }

    async sendStreamingMessage(run, content) {
        const message = requireString(content, 'message');
        try {
            await run.streamingAdapter.sendMessage(message);
        } catch (error) {
            this.failStreamingRun(run, error);
            run.conversation.status = 'failed';
            throw error;
        }
        const timestamp = new Date().toISOString();
        if (run.conversation.status === 'waitingForInput') run.turnIndex += 1;
        const messageId = `${run.id}-user-${run.conversation.messages.length}`;
        run.conversation.messages.push(createMessage(messageId, 'user', message, timestamp, undefined, nextRunSequence(run)));
        const userMessage = run.conversation.messages.at(-1);
        run.conversation.status = 'running';
        run.turnActive = true;
        await this.persistCheckpoint(run);
        emitRunEvent(run, { type: 'userMessage', userMessage });
        emitRunEvent(run, { state: 'running', type: 'state' });
    }

    setQueuedMessage(runId, sessionId, content, revision) {
        const run = this.requireRun(runId);
        requireQueuedMessageSession(run, sessionId);
        if (!Number.isSafeInteger(revision) || revision < 0) throw new Error('Invalid queued agent message revision');
        if (revision < run.queuedMessageRevision) return { accepted: false };
        if (typeof content !== 'string') throw new Error('Invalid queued agent message');
        run.queuedMessageRevision = revision;
        run.queuedMessage = content.trim().length > 0 ? { content, revision } : null;

        return { accepted: true };
    }

    answerQuestion(runId, requestId, answers) {
        const run = this.requireStreamingRun(runId);
        if (!answers || typeof answers !== 'object' || Array.isArray(answers)) throw new Error('Missing streaming question answers');

        return queueInteractionWrite(run, async () => {
            const pendingQuestions = run.pendingQuestions;
            const secretQuestionIds = new Set(pendingQuestions.filter(({ isSecret }) => isSecret).map(({ id }) => id));
            const content = Object.entries(answers)
                .map(([questionId, answer]) => (
                    `${questionId}: ${secretQuestionIds.has(questionId) ? '[secret]' : Array.isArray(answer) ? answer.join(', ') : answer}`
                ))
                .join('\n');
            run.secretValues ??= new Set();
            secretAnswerValues(pendingQuestions, answers).forEach((answer) => run.secretValues.add(answer));
            try {
                await run.streamingAdapter.answerQuestion(requestId, answers);
            } catch (error) {
                this.failStreamingRun(run, error);
                run.conversation.status = 'failed';
                throw error;
            }
            const timestamp = new Date().toISOString();
            run.conversation.messages.push(createMessage(
                `${run.id}-answer-${run.conversation.messages.length}`,
                'user',
                content,
                timestamp,
                undefined,
                nextRunSequence(run),
            ));
            const userMessage = run.conversation.messages.at(-1);
            run.conversation.status = 'running';
            run.waitingForQuestion = false;
            run.pendingQuestions = [];
            await this.persistCheckpoint(run);
            emitRunEvent(run, { type: 'questionAnswered', userMessage });
            emitRunEvent(run, { state: 'running', type: 'state' });
        });
    }

    finish(runId) {
        const run = this.requireStreamingRun(runId);
        run.finishing = true;
        run.queuedMessage = null;
        if (!run.turnActive || run.waitingForQuestion) run.child.stdin.end();
    }

    stopAll() {
        const completions = [];
        for (const run of this.processes.values()) {
            run.cancelled = true;
            completions.push(Promise.all([this.ensureTermination(run), run.closed]));
        }

        return Promise.all(completions);
    }

    ensureTermination(run) {
        run.termination ??= this.terminateProcessTree(run.child);

        return run.termination;
    }

    handleCodexRuntimeEvent(event) {
        if (!this.codexRuntimeService) return;
        if (event.kind === 'unavailable') {
            this.codexRuntimeService.publishUnavailable(event.observedAt);
            return;
        }
        this.codexRuntimeService.publishRateLimits(event.payload, event.observedAt, event.kind === 'update');
    }

    handleOutput(runId, channel, chunk) {
        const run = this.processes.get(runId);
        if (!run) return;

        const content = chunk.toString();
        if (channel === 'stdout' && run.protocolLines) {
            run.protocolLines.push(chunk);
            return;
        }
        if (channel === 'stdout' && run.parser) {
            run.parser.push(chunk);
            return;
        }
        if (channel === 'stderr') {
            run.stderrBuffer += content;
            const filtered = filterCompleteStderrLines(run.stderrBuffer);
            run.stderrBuffer = filtered.remainder;
            if (filtered.content.length === 0) return;
            this.recordStderr(run, filtered.content);
            return;
        }
        this.recordOutput(runId, channel, content);
    }

    recordStderr(run, content) {
        const parts = content.split(/(\r\n|\r|\n)/u);
        for (let index = 0; index < parts.length; index += 2) {
            const line = parts[index];
            const delimiter = parts[index + 1] ?? '';
            if (line.length === 0 && delimiter.length === 0) continue;
            if (run.agent !== 'codex' || !isCodexCacheError(line)) {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
                continue;
            }
            if (run.codexCacheErrorReported) continue;
            run.codexCacheErrorReported = true;
            const diagnostic = run.stderrHandling.then(async () => {
                const message = await this.diagnoseCodexCacheError(line, run.executable, run.environment);
                this.recordOutput(run.id, 'stderr', `${message}\n`);
            });
            run.stderrHandling = diagnostic.catch(() => {
                this.recordOutput(run.id, 'stderr', `${line}${delimiter}`);
            });
        }
    }

    handleStreamingLine(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        let message;
        try {
            message = JSON.parse(line);
        } catch {
            this.handleMalformedOutput(runId, line);
            return;
        }
        run.protocolHandling = run.protocolHandling
            .then(() => run.streamingAdapter.handleMessage(message))
            .catch((error) => {
                this.failStreamingRun(run, error);
            });
    }

    recordOutput(runId, channel, content) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        const safeContent = redactSecrets(content, run.secretValues);
        if (channel === 'stdout') {
            const { segment } = appendAssistantOutput(run, safeContent, timestamp);
            if (segment.length === 0) return;
            emitRunEvent(run, { content: segment, type: 'output' });
            return;
        }
        run.stderr += safeContent;
        run.conversation.events.push(createEvent(
            `${runId}-error-${run.conversation.events.length}`,
            'error',
            safeContent,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: safeContent, type: 'error' });
    }

    flushStderr(runId) {
        const run = this.processes.get(runId);
        if (!run || run.stderrBuffer.length === 0) return;

        const content = run.stderrBuffer;
        run.stderrBuffer = '';
        if (!isHiddenStderrLine(content)) this.recordStderr(run, content);
    }

    handleProviderEvent(runId, providerEvent) {
        const run = this.processes.get(runId);
        if (!run) return;

        const timestamp = new Date().toISOString();
        run.turnStarted = run.turnStarted || providerEvent.turnStarted;
        run.missingSession = run.missingSession || providerEvent.missingSession;
        providerEvent.changedPaths.forEach((filePath) => run.changedPaths.add(filePath));
        if (providerEvent.conversationId) run.providerConversationId = providerEvent.conversationId;
        if (providerEvent.usage) run.turnUsage = providerEvent.usage;
        for (const transcriptEvent of providerEvent.transcriptEvents) {
            run.conversation.events.push(createEvent(
                `${runId}-provider-${run.conversation.events.length}`,
                transcriptEvent.toolType,
                transcriptEvent.content,
                timestamp,
                nextRunSequence(run),
            ));
        }
        if (providerEvent.assistantText.length > 0) {
            const { segment } = appendAssistantOutput(run, providerEvent.assistantText, timestamp);
            if (segment.length > 0) emitRunEvent(run, { content: segment, type: 'output' });
        } else if (providerEvent.errorText.length > 0 && !run.reportedProviderErrors.has(providerEvent.errorText)) {
            const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
            run.reportedProviderErrors.add(providerEvent.errorText);
            run.stderr += `${separator}${providerEvent.errorText}`;
            run.conversation.events.push(createEvent(
                `${runId}-error-${run.conversation.events.length}`,
                'error',
                providerEvent.errorText,
                timestamp,
                nextRunSequence(run),
            ));
            emitRunEvent(run, { content: providerEvent.errorText, type: 'error' });
        }
    }

    async handleStreamingEvent(runId, event) {
        const run = this.processes.get(runId);
        if (!run) return;
        const timestamp = new Date().toISOString();

        if (event.type === 'sessionStarted') {
            run.providerConversationId = event.conversationId;
            return;
        }
        if (event.type === 'turnStarted') {
            run.assistantItemIndex = 0;
            run.assistantItems.clear();
            run.currentAssistantMessageId = null;
            run.turnStarted = true;
            return;
        }
        if (event.type === 'assistantStarted') {
            startAssistantItem(run, requireString(event.itemId, 'assistant item id'));
            return;
        }
        if (event.type === 'assistant') {
            const safeContent = redactSecrets(event.content, run.secretValues);
            const itemId = run.agent === 'codex'
                ? requireString(event.itemId, 'assistant item id')
                : event.itemId;
            const { message, segment } = appendAssistantOutput(run, safeContent, timestamp, itemId);
            if (segment.length > 0) {
                emitRunEvent(run, { content: segment, messageId: message.id, sequence: message.sequence, type: 'output' });
            }
            return;
        }
        if (event.type === 'changedPaths') {
            event.paths.forEach((filePath) => run.changedPaths.add(filePath));
            return;
        }
        if (event.type === 'activity') {
            const safeActivity = redactActivity(event.activity, run.secretValues);
            const providerItemId = requireString(safeActivity.providerItemId, 'activity providerItemId');
            const currentIndex = run.activityEventIndexes.get(providerItemId);
            let activity;
            if (currentIndex !== undefined) {
                const current = run.conversation.events[currentIndex];
                activity = createActivityEvent(safeActivity, current.id, timestamp, current.sequence);
                run.conversation.events[currentIndex] = activity;
            } else {
                const sequence = nextRunSequence(run);
                activity = createActivityEvent(
                    safeActivity,
                    `${runId}-activity-${sequence}`,
                    timestamp,
                    sequence,
                );
                run.activityEventIndexes.set(providerItemId, run.conversation.events.length);
                run.conversation.events.push(activity);
            }
            emitRunEvent(run, { activity, type: 'agentActivity' });
            return;
        }
        if (event.type === 'transcript') {
            const safeContent = redactSecrets(event.content, run.secretValues);
            run.conversation.events.push(createEvent(
                `${runId}-provider-${run.conversation.events.length}`,
                event.toolType,
                safeContent,
                timestamp,
                nextRunSequence(run),
            ));
            return;
        }
        if (event.type === 'error') {
            this.recordOutput(runId, 'stderr', event.content);
            return;
        }
        if (event.type === 'fatal') {
            this.failStreamingRun(run, new Error(event.content));
            return;
        }
        if (event.type === 'sessionFailed') {
            run.missingSession = event.missingSession;
            this.failStreamingRun(run, new Error(event.content));
            return;
        }
        if (event.type === 'question') {
            run.conversation.status = 'waitingForInput';
            run.waitingForQuestion = true;
            run.pendingQuestions = event.questions;
            await this.persistCheckpoint(run);
            emitRunEvent(run, { questions: event.questions, requestId: event.requestId, state: 'waitingForInput', type: 'question' });
            return;
        }
        if (event.type !== 'turnCompleted') return;

        completeAssistantOutput(run, timestamp);
        run.turnActive = false;
        run.waitingForQuestion = false;
        run.missingSession = run.missingSession || event.missingSession;
        if (event.missingSession) run.finishing = true;
        if (event.usage) run.conversation.usage = accumulateUsage(run.conversation.usage, event.usage);
        if (event.error) {
            this.failStreamingRun(run, new Error(event.error));
            return;
        }
        if (run.finishing) {
            run.child.stdin.end();
            return;
        }
        if (run.queuedMessage) {
            const { content, revision } = run.queuedMessage;
            run.conversation.status = 'waitingForInput';
            await this.sendStreamingMessage(run, content);
            run.queuedMessage = null;
            run.sentQueuedMessageRevision = revision;
            return;
        }
        const synchronizedMessage = run.conversation.messages.at(-1);
        if (synchronizedMessage) updateProviderSession(run, synchronizedMessage.id, timestamp);
        run.conversation.status = 'waitingForInput';
        run.conversation.completedAt = null;
        run.conversation.events.push(createEvent(
            `${runId}-turn-${run.turnIndex}-completed`,
            'turnCompleted',
            '',
            timestamp,
            nextRunSequence(run),
        ));
        await this.persistCheckpoint(run);
        emitRunEvent(run, { state: 'waitingForInput', type: 'state' });
    }

    handleMalformedOutput(runId, line) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (!run.streaming) {
            const timestamp = new Date().toISOString();
            const message = `Malformed ${run.agent} JSONL event: ${line}`;
            run.conversation.events.push(createEvent(
                `${runId}-malformed-${run.conversation.events.length}`,
                'diagnostic',
                message,
                timestamp,
                nextRunSequence(run),
            ));
            return;
        }
        this.failStreamingRun(run, new Error(`Malformed ${run.agent} JSONL event`));
    }

    handleError(runId, error) {
        const run = this.processes.get(runId);
        if (!run) return;

        if (run.streaming) {
            this.failStreamingRun(run, error);
            return;
        }
        const timestamp = new Date().toISOString();
        const message = error instanceof Error ? error.message : 'Agent process failed';
        run.stderr += message;
        run.conversation.events.push(createEvent(
            `${runId}-error-${run.conversation.events.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
    }

    failStreamingRun(run, errorValue) {
        if (run.streamingFailure) return run.termination;

        const error = errorValue instanceof Error ? errorValue : new Error('Streaming agent failed');
        const message = redactSecrets(error.message, run.secretValues);
        const timestamp = new Date().toISOString();
        run.streamingFailure = new Error(message);
        run.conversation.status = 'failed';
        run.queuedMessage = null;
        run.waitingForQuestion = false;
        run.pendingQuestions = [];
        const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
        run.stderr += `${separator}${message}`;
        run.conversation.events.push(createEvent(
            `${run.id}-error-${run.conversation.events.length}`,
            'error',
            message,
            timestamp,
            nextRunSequence(run),
        ));
        emitRunEvent(run, { content: message, type: 'error' });
        emitRunEvent(run, { state: 'failed', type: 'state' });
        try {
            run.child.stdin.end();
        } catch {
            // Process-tree termination below remains authoritative.
        }

        return this.ensureTermination(run);
    }

    async handleClose(runId, exitCode) {
        const run = this.processes.get(runId);
        if (!run) return;

        try {
            if (run.termination) await run.termination;
            else await this.terminateDescendantProcesses(run.child.pid);
            run.parser?.finish();
            run.protocolLines?.finish();
            await run.protocolHandling;
            this.flushStderr(runId);
            await run.stderrHandling;
            const completedAt = new Date().toISOString();
            if (run.streaming && !run.finishing && !run.cancelled && !run.streamingFailure && !run.suspended) {
                run.streamingFailure = new Error('Streaming agent process exited before Finish');
                const separator = run.stderr.length > 0 && !run.stderr.endsWith('\n') ? '\n' : '';
                run.stderr += `${separator}${run.streamingFailure.message}`;
            }
            const succeeded = exitCode === 0
                && !run.missingSession
                && !run.cancelled
                && !run.streamingFailure
                && (!run.streaming || run.finishing);
            completeAssistantOutput(run, completedAt);
            if (succeeded) {
                const synchronizedMessage = run.conversation.messages.at(-1);
                updateProviderSession(run, synchronizedMessage.id, completedAt);
                if (run.turnUsage) run.conversation.usage = accumulateUsage(run.conversation.usage, run.turnUsage);
            }
            const preserveWaitingState = run.suspended && run.conversation.status === 'waitingForInput';
            run.conversation.completedAt = preserveWaitingState ? null : completedAt;
            run.conversation.status = preserveWaitingState
                ? 'waitingForInput'
                : run.cancelled ? 'cancelled' : succeeded ? 'completed' : 'failed';
            run.conversation.events.push(createEvent(
                `${runId}-closed`,
                'closed',
                String(exitCode),
                completedAt,
                nextRunSequence(run),
            ));
            console.log('[agent:complete]', {
                completedAt,
                durationMs: Date.parse(completedAt) - Date.parse(run.startedAt),
                executionId: run.request.executionId ?? null,
                exitCode,
                pid: run.child.pid,
                runId,
            });
            await run.persistence;
            await this.persistConversation(run);
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
            emitRunEvent(run, { reference: run.reference, status: run.conversation.status, type: 'closed' });
            if (run.onComplete) run.onComplete(succeeded ? 0 : exitCode || 1, run);
        } catch (error) {
            if (run.onCompletionError) run.onCompletionError(error);
        } finally {
            this.processes.delete(runId);
            this.runningConversationIds.delete(run.conversation.id);
        }
    }

    requireRun(runId) {
        const run = this.processes.get(runId);
        if (!run) throw new Error(`Agent run is not active: ${runId}`);

        return run;
    }

    persistCheckpoint(run) {
        const snapshot = { ...run, conversation: structuredClone(run.conversation) };
        const write = run.persistence.then(() => this.persistConversationCheckpoint(snapshot));
        run.persistence = write.catch(() => undefined);

        return write;
    }

    requireStreamingRun(runId) {
        const run = this.requireRun(runId);
        if (!run.streaming) throw new Error(`Agent run is not streaming: ${runId}`);

        return run;
    }
}

module.exports = { AgentRunnerService };

